import styled from 'styled-components';
const Viewrs = (props)=>{
    return(
        <Container>
            <Wrap>
            <img src="/images/viewers-disney.png"  alt=''/>
                <video autoPlay={true} loop={true} playsInline={true}>
                    <source src='/video/1564674844-disney.mp4'type ='video/mp4'/>
                </video>
            </Wrap>
            <Wrap>
                <img src="/images/viewers-marvel.png" alt='' />
                <video autoPlay={true} loop={true} playsInline={true}>
                    <source src='/video/1564676115-marvel.mp4'type ='video/mp4'/>
                </video>
            </Wrap>
            <Wrap>
                <img src="/images/viewers-national.png" alt='' />
                <video autoPlay={true} loop={true} playsInline={true}>
                    <source src='/video/1564676296-national-geographic.mp4'type ='video/mp4'/>
                </video>
            </Wrap>
            <Wrap>
                <img src="/images/viewers-pixar.png" alt='' />
                <video autoPlay={true} loop={true} playsInline={true}>
                    <source src='/video/1564676714-pixar.mp4'type ='video/mp4'/>
                </video>
            </Wrap>
            <Wrap>
                <img src="/images/viewers-starwars.png" alt='' />
                <video autoPlay={true} loop={true} playsInline={true}>
                    <source src='/video/1608229455-star-wars.mp4'type ='video/mp4'/>
                </video>
            </Wrap>

        </Container>
    );

}


const Container =styled.div`
margin-top:30px;
padding : 30px 30px 26px;
display : grid;
grid-gap: 25px;
gap: 25px;
grid-template-columns: repeat(5,minmax(0,1fr));

@media (max-width:768px){
    grid-template-columns: repeat(1,minmax(0,1fr));   
}
`;
const Wrap = styled.div`
padding-top: 56.25%;
border-radius:10px;
box-shadow:rgb(0 0 0 / 69%) 0px 26px 30px -10px,
    rgb(0 0 0 / 73%) 0px 16px 10px -10px;
    cursor: pointer;
    overflow: hidden;
    position: relative;
    border : 3px solid rgba(249,249,249,0.1);
    transition: transform 300ms var(--ease-standard, ease), border-color 300ms var(--ease-standard, ease);

    img{
        inset:0px;
        display:block;
        width:100%;
        height:100%;
        object-fit:cover;
        opacity:1;
        position: absolute;
        z-index:1;
    }
     video{

        top:0px;
        width:100%;
        height:100%;
        object-fit: cover;
        position:absolute;
        z-index:0;
        opacity:0;


            }
            &:hover{

            box-shadow:rgb(0 0 0 / 69%) 0px 26px 30px -10px,
    rgb(0 0 0 / 73%) 0px 16px 10px -10px;
    transform: scale(1.04); 
    border-color: rgba(249, 249, 249, 0.8);

    video{
        transition: opacity 300ms var(--ease-standard, ease);
                    opacity:1;
                }
        }

`;
export default Viewrs;
